package vn.covie.notifications.application; import java.util.*; import org.springframework.stereotype.Component; import vn.covie.needs.persistence.NeedRequestRepository; import vn.covie.notifications.model.NotificationType; import vn.covie.outbox.application.*; import vn.covie.realtime.SseSignal;
@Component public class NeedNotificationHandler implements OutboxEventHandler {private final NeedRequestRepository needs;private final NotificationService notifications;public NeedNotificationHandler(NeedRequestRepository n,NotificationService s){needs=n;notifications=s;}public boolean supports(String type){return Set.of("NEED_RESPONSE_CREATED","NEED_RESPONSE_UPDATED","NEED_RESPONSE_WITHDRAWN","NEED_FULFILLED","NEED_EXPIRED","NEED_CANCELLED").contains(type);}public List<SseSignal> handle(OutboxEventContext event){var need=needs.findById(event.aggregateId()).orElseThrow();if("NEED_CANCELLED".equals(event.eventType()))return List.of(new SseSignal(need.getBuyerUserId(),"sync-required",Map.of()));NotificationType type=switch(event.eventType()){case "NEED_RESPONSE_CREATED"->NotificationType.NEED_RESPONSE_RECEIVED;case "NEED_RESPONSE_UPDATED"->NotificationType.NEED_RESPONSE_UPDATED;case "NEED_RESPONSE_WITHDRAWN"->NotificationType.NEED_RESPONSE_WITHDRAWN;case "NEED_FULFILLED"->NotificationType.NEED_FULFILLED;case "NEED_EXPIRED"->NotificationType.NEED_EXPIRED;default->throw new IllegalArgumentException();};var result=notifications.createFromOutbox(event.eventId(),need.getBuyerUserId(),type,"Need update","Your request has an update.","NEED_REQUEST",need.getId(),Map.of("needRequestId",need.getId().toString()));String signal=switch(event.eventType()){case "NEED_RESPONSE_CREATED"->"need-response.created";case "NEED_RESPONSE_UPDATED"->"need-response.updated";case "NEED_RESPONSE_WITHDRAWN"->"need-response.withdrawn";case "NEED_FULFILLED"->"need-request.fulfilled";default->"sync-required";};List<SseSignal> signals=new ArrayList<>();if(result.created())signals.add(new SseSignal(need.getBuyerUserId(),"notification.created",Map.of("notificationId",result.notificationId().toString())));signals.add(new SseSignal(need.getBuyerUserId(),signal,Map.of("needRequestId",need.getId().toString())));return signals;}}
